// C implementation of vstodo cmdPull header
//\n// NOTE: This is a skeleton implementation for migration purposes.\n// It follows the Go cmd_pull.go command interface.\n//\n// This file cannot be compiled/verified locally per AGENTS.md constraints\n// (no C compiler available). It is provided as the intended C replacement\n// for cmd_pull.go.\n\n#ifndef VSTODO_C_CMD_PULL_H\n#define VSTODO_C_CMD_PULL_H\n\n// Pull from a remote repository (fetch + merge).\n// Equivalent to Go cmdPull function.\n// app — vstodo application context pointer\n// args — remote name or URL arguments\n// arg_count — number of arguments\n//\n// Returns 0 on success, negative error code on failure.\nint cmd_pull(void *app, const char **args, int arg_count);\n\n#endif // VSTODO_C_CMD_PULL_H